def norm(s): return re.sub(r'[^a-z0-9]+','',s.lower().replace('²','^2'))
def ok(s,aliases): return any(norm(s)==norm(a) for a in aliases)
def main():
 ap=argparse.ArgumentParser(); ap.add_argument('--model',default='qwen35-27b-dense'); ap.add_argument('-n',type=int,default=5); ap.add_argument('--temperature',type=float,default=.9); ap.add_argument('--seed',type=int,default=91000); ap.add_argument('--output',required=True); a=ap.parse_args(); rows=[]
 for i,(cat,prompt,gold) in enumerate(CASES):
  msgs=[{'role':'user','content':prompt}]; g=ep.complete('http://127.0.0.1:1234/v1/chat/completions',a.model,msgs,a.seed+i,0,1,80,20); pool=[]
  for j in range(a.n): pool.append(ep.complete('http://127.0.0.1:1234/v1/chat/completions',a.model,msgs,a.seed+10000+i*a.n+j,a.temperature,.95,80,20))
  picks={p:ep.select(pool,p)[0] for p in ('likelihood','low_entropy','consensus')}; r={'i':i,'category':cat,'prompt':prompt,'gold':gold,'greedy':g['text'],'greedy_ok':ok(g['text'],gold),'oracle':any(ok(x['text'],gold) for x in pool),'pool':[x['text'] for x in pool]}
  for p,x in picks.items(): r[p]=x['text']; r[p+'_ok']=ok(x['text'],gold)
  rows.append(r); print(json.dumps(r,ensure_ascii=False),flush=True)
 methods=['greedy','likelihood','low_entropy','consensus']; summary={'total':len(rows),'oracle':sum(r['oracle'] for r in rows)}
 for m in methods: summary[m]=sum(r[m+'_ok'] for r in rows)
 for m in methods[1:]: summary[m+'_fixes']=sum(not r['greedy_ok'] and r[m+'_ok'] for r in rows); summary[m+'_regressions']=sum(r['greedy_ok'] and not r[m+'_ok'] for r in rows)
 cats={};
 for c in sorted(set(r['category'] for r in rows)): cats[c]={m:sum(r[m+'_ok'] for r in rows if r['category']==c) for m in methods}|{'total':sum(r['category']==c for r in rows)}
 out={'config':vars(a),'summary':summary,'categories':cats,'rows':rows}; Path(a.output).write_text(json.dumps(out,ensure_ascii=False,indent=2)); print('FINAL '+json.dumps({'summary':summary,'categories':cats}));
if __name__=='__main__': main()
